INSERT INTO `blog_translations` (`id`, `title`, `description`, `abbr`, `for_id`) VALUES
(1, 'Mẹo giúp cây xanh tốt nhờ vỏ trứng', '<p>Vỏ trứng có thể giúp tiêu diệt sâu bệnh, cung cấp chất dinh dưỡng cho cây.</p>\r\n\r\n<article>\r\n<p>1. Bổ sung canxi&nbsp;</p>\r\n\r\n<figure data-size=\"js\" itemprop=\"associatedMedia image\" itemscope=\"\" itemtype=\"http://schema.org/ImageObject\"><img alt=\"meo-giup-cay-xanh-tot-nho-vo-trung\" data-ll-status=\"loaded\" data-src=\"https://i1-giadinh.vnecdn.net/2016/09/05/qua-trung-1a-2992-1473066361.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=VTIOfvCoKwlHf-UBpEY5UA\" intrinsicsize=\"680x0\" itemprop=\"contentUrl\" loading=\"lazy\" src=\"https://i1-giadinh.vnecdn.net/2016/09/05/qua-trung-1a-2992-1473066361.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=VTIOfvCoKwlHf-UBpEY5UA\" />\r\n<figcaption itemprop=\"description\">\r\n<p>&nbsp;</p>\r\n</figcaption>\r\n</figure>\r\n\r\n<p>Canxi là một trong những dưỡng chất giúp cho thân cây cứng cáp, khỏe mạnh. Bạn hãy đập vụn vỏ trứng, trộn vào đất. Sau vài tháng, rễ cây có thể hấp thụ canxi có trong vỏ trứng. Các cây con&nbsp;cũng sẽ tăng cường khả năng sống sót hơn. Cà chua là một trong những cây đặc biệt cần canxi.</p>\r\n\r\n<p>2. Làm khay gieo hạt giống</p>\r\n\r\n<figure data-size=\"js\" itemprop=\"associatedMedia image\" itemscope=\"\" itemtype=\"http://schema.org/ImageObject\"><img alt=\"meo-giup-cay-xanh-tot-nho-vo-trung-1\" data-ll-status=\"loaded\" data-src=\"https://i1-giadinh.vnecdn.net/2016/09/05/qua-trung-2-1496-1473066361.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=JCpMIzF4Zzc82yz09kuPIg\" intrinsicsize=\"680x0\" itemprop=\"contentUrl\" loading=\"lazy\" src=\"https://i1-giadinh.vnecdn.net/2016/09/05/qua-trung-2-1496-1473066361.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=JCpMIzF4Zzc82yz09kuPIg\" />\r\n<figcaption itemprop=\"description\">\r\n<p>&nbsp;</p>\r\n</figcaption>\r\n</figure>\r\n\r\n<p>Bạn hãy lựa những vỏ trứng còn nguyên vẹn để làm nơi đổ đất, gieo hạt. Để khử trùng, bạn nên luộc trứng, khéo léo bóc để một nửa vỏ còn nguyên vẹn. Dùng đinh đục lỗ nhỏ ở đáy vỏ để thoát nước. Ưu điểm của khay gieo hạt này là có thể phân hủy trong đất sau khi sử dụng xong, giúp bạn bảo vệ môi trường.</p>\r\n\r\n<p>3. Diệt sâu bệnh</p>\r\n\r\n<figure data-size=\"js\" itemprop=\"associatedMedia image\" itemscope=\"\" itemtype=\"http://schema.org/ImageObject\"><img alt=\"meo-giup-cay-xanh-tot-nho-vo-trung-2\" data-ll-status=\"loaded\" data-src=\"https://i1-giadinh.vnecdn.net/2016/09/02/Untitled-4-6148-1472784351.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=FOjnq-Io4Yqt3SB4iUzmKg\" intrinsicsize=\"680x0\" itemprop=\"contentUrl\" loading=\"lazy\" src=\"https://i1-giadinh.vnecdn.net/2016/09/02/Untitled-4-6148-1472784351.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=FOjnq-Io4Yqt3SB4iUzmKg\" />\r\n<figcaption itemprop=\"description\">\r\n<p>&nbsp;</p>\r\n</figcaption>\r\n</figure>\r\n\r\n<p>Ốc sên vốn là loại ăn lá, gây hại cho rau nhưng khó tiêu diệt vì chúng thường ẩn nấp sâu dưới đất vào ban ngày. Một số người làm vườn rắc vỏ trứng để diệt ốc sên. Vỏ trứng vụn rải trên đất cũng có thể đẩy lùi một vài loại sâu bệnh không chịu nổi mùi trứng.</p>\r\n\r\n<p>4. Giúp đất thông thoáng, ngăn chặn cỏ dại</p>\r\n\r\n<figure data-size=\"js\" itemprop=\"associatedMedia image\" itemscope=\"\" itemtype=\"http://schema.org/ImageObject\"><img alt=\"meo-giup-cay-xanh-tot-nho-vo-trung-3\" data-ll-status=\"loaded\" data-src=\"https://i1-giadinh.vnecdn.net/2016/09/02/Untitled-6-6167-1472784351.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=Jisoy3QvwruknL5ZuNQw0Q\" intrinsicsize=\"680x0\" itemprop=\"contentUrl\" loading=\"lazy\" src=\"https://i1-giadinh.vnecdn.net/2016/09/02/Untitled-6-6167-1472784351.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=Jisoy3QvwruknL5ZuNQw0Q\" />\r\n<figcaption itemprop=\"description\">\r\n<p>&nbsp;</p>\r\n</figcaption>\r\n</figure>\r\n\r\n<p>Nếu bạn có nhiều vỏ trứng, bạn có thể đập vụn, rắc chúng kín bề mặt đất. Nhờ vậy, cỏ dại rất khó có cơ hội để mọc. Lớp vỏ trứng giúp đất&nbsp;có nhiều khoảng thoáng, không bị úng ngập.</p>\r\n\r\n<p><strong>Lam Huyền</strong><br />\r\nẢnh:&nbsp;<em>Gardenista</em></p>\r\n\r\n<p><em>(<a href=\"http://giadinh.vnexpress.net/tin-tuc/nha-dep/tu-van-nha-dep/meo-giup-cay-xanh-tot-nho-vo-trung-3461850.html?utm_source=home&amp;utm_medium=box_giadinh_home&amp;utm_campaign=boxtracking\">http://giadinh.vnexpress.net/tin-tuc/nha-dep/tu-van-nha-dep/meo-giup-cay-xanh-tot-nho-vo-trung-3461850.html?utm_source=home&amp;utm_medium=box_giadinh_home&amp;utm_campaign=boxtracking</a>)</em></p>\r\n</article>\r\n', 'en', 1);

