INSERT INTO `products_translations` (`id`, `title`, `description`, `basic_description`, `price`, `old_price`, `abbr`, `for_id`) VALUES
(3, 'Hạt Giống Rau Mầm Bông Cải Xanh Italia 20G', '<p><strong>MÔ TẢ:</strong><br />\r\n- Khối lượng: Gói 20g<br />\r\n- Kích thước: dài x rộng: 19x13cm<br />\r\n- Hiện shop có hàng gói lớn 1kg (28x20cm) với giá tiết kiệm,&nbsp;<br />\r\nQuý khách có thể tìm sản phẩm với tên \"Hạt Giống Mầm Bông Cải Xanh Italia 1kg\" hoặc link<br />\r\nhttps://shopee.vn/Hạt-Giống-Mầm-Bông-Cải-Xanh-Italia-1kg-i.237010465.5140050327</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:</strong><br />\r\n- Cây mầm thân nhuyễn, vị nồng nhẹ, thơm ngon, chứa nhiều dinh dưỡng quý</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Hợp chất trong mầm bông cải xanh giúp giảm cân, tăng cường sức khỏe.<br />\r\n- Mầm bông cải xanh có thể giúp khắc phục bệnh đái tháo đường.<br />\r\n- Ngăn ngừa bệnh ung thư, mầm bông cải xanh có tác dụng chống ung thu và&nbsp;<br />\r\nngăn ngừa hội chứng oxy hóa cao hơn rất &nbsp;nhiều lần so với bông cải trưởng thành.<br />\r\n- Có lợi cho tim mạch, giúp xương chắc khỏe<br />\r\n- Giải độc cơ thể, cải thiện chức năng hô hấp, hỗ trợ điều trị đa xơ cứng<br />\r\n- Mầm bông cải xanh có thể giảm một số vấn đề liên quan đến chấn thương não</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Thu hoach: 5-7 ngày sau khi gieo.<br />\r\n- Năng suất: 650 – 750g rau/100g hạt.<br />\r\nKỹ thuật trồng mầm bông cải xanh: xem thêm trong bao bì</p>\r\n\r\n<p>**************************************************************************************************</p>\r\n\r\n<p>Cửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '16500', '', 'en', 3),
(4, 'Túi Lớn 1Kg  Hạt Giống Cải Bẹ Xanh Dễ Trồng', '<p><strong>MÔ TẢ:</strong><br />\r\n- Khối lượng: Gói lớn 1kg<br />\r\n- Kích thước: dài x rộng: 28x20cm<br />\r\n- Shop hiện có bán hàng gói nhỏ Gói 20g, Gói 50g, Gói 100g. Quý khách có thể tìm sản phẩm với&nbsp;<br />\r\ntên \"Hạt Giống Cải Bẹ Xanh (Cải Xanh Mỡ)\" hoặc link https://shopee.vn/Hạt-Giống-Cải-Bẹ-Xanh-(Cải-Xanh-Mỡ)-i.237010465.6025822896</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:</strong><br />\r\n- Giống được chọn lọc kỹ, kháng bệnh tốt, năng suất cao 2 - 2.5 tấn/ha, có thể trồng quanh năm.<br />\r\n- Cây lớn, màu xanh bóng, cao khoảng 25 - 40 cm, phẩm chất ngon.<br />\r\n- Không có xơ, độ nông thấp và không trở ngồng khi kéo dài thời gian thu hoạch trên đồng ruộng.</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Tốt cho tim mạch.<br />\r\n- Chống lão hóa da.&nbsp;<br />\r\n- Hỗ trợ hệ tiêu hóa.&nbsp;<br />\r\n- Phòng chống ung thư bàng quang.&nbsp;</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Có thể dùng để trồng rau lớn hoặc rau non.<br />\r\n- Thời gian thu hoạch: 30 - 40 ngày sau khi trồng.<br />\r\n- Khoảng cách trồng: 20x22cm.&nbsp;<br />\r\n- Mật độ trồng/1000m2: Cấy 70 - 80g, Sạ 300 - 400g<br />\r\n- Kỹ thuật trồng chậu: Xem trong bao bì</p>\r\n\r\n<p>**************************************************************************************************</p>\r\n\r\n<p>????Cửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '169000', '', 'en', 4),
(5, 'Hạt Giống Hoa Cúc Sao Băng 100Mg', '<p><strong>MÔ TẢ:&nbsp;&nbsp; &nbsp;</strong><br />\r\n- Khối lượng: Gói 100mg<br />\r\n- Kích thước: dài x rộng: 19x13cm</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:</strong><br />\r\n- Đây là loại hoa đẹp, cây cao 25 - 30cm, hoa nhỏ xinh màu vàng rất phù hợp để trồng thảm, trồng chậu đứng, chậu treo ban công.<br />\r\n- Hoa Sao băng sinh trưởng nhanh, thích hợp với khí hậu nhiệt đới, có thể trong quanh năm.&nbsp;<br />\r\n- Hoa cúc sao băng có thể trồng thành từng cụm hay thành vườn, thành hàng… để làm thảm hoa sân vườn, quán café, hay viền lối đi…</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Thời gian hạt nảy mầm: 3 - 5 ngày&nbsp;<br />\r\n- Thời gian ra hoa khoảng 40 - 50 ngày<br />\r\n- Hướng dẫn trồng chậu: xem trong bao bì &nbsp;&nbsp;</p>\r\n\r\n<p>**************************************************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '20800', '', 'en', 5),
