(177, 'Hạt Giống Cà Rốt 2G', '<p>&nbsp;- Khối lượng: Gói 2g&nbsp;&nbsp; &nbsp;<br />\r\n- Kích thước: dài x rộng: 19x13cm</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:</strong><br />\r\n- &nbsp;Phát triển mạnh, chịu nhiệt cao. Củ suôn đều, thịt dày, lõi nhỏ, màu đỏ cam, dài 18 - 20 cm,&nbsp;<br />\r\nđường kính khoảng 6 cm, nặng 250 - 300g , ăn ngon ngọt .&nbsp;</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Cải thiện tầm nhìn.&nbsp;<br />\r\n- Ổn định huyết áp.&nbsp;<br />\r\n- Ngừa ung thư.<br />\r\n- Làm đẹp da.&nbsp;<br />\r\n- Giảm cholesterol.&nbsp;<br />\r\n- Bảo vệ tim mạch.&nbsp;<br />\r\n- Thải độc cơ thể.<br />\r\n- Ngăn ngừa mất trí nhớ</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Thu hoạch: 100 - 110 ngày sau gieo&nbsp;<br />\r\n- Khoảng cách trồng: lên luống rộng 1,0 - 1,2 m , cây cách cây trên luống 20cm&nbsp;<br />\r\n- Mật độ trồng / 1000m2: 2.8 - 3.2kg<br />\r\nKỹ thuật trồng chậu: xem trong bao bì<br />\r\n************************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '16000', '', 'en', 177),
(178, 'Hạt Giống Cà Chua Bi Trồng Chậu 100Mg', '<p>- Khối lượng: Gói 100mg<br />\r\n- Kích thước: dài x rộng: 19x13cm</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:</strong><br />\r\n- Sinh trưởng tốt, dễ trồng, có thể trồng quanh năm.&nbsp;<br />\r\n- Cây lùn, cao khoảng 30 - 35cm, thích hợp trồng chậu.<br />\r\n- Trái tròn, nhỏ, mọc thành từng chùm.&nbsp;<br />\r\n- Cây cà chua nhìn rất dễ thương, đẹp, dùng để trang trí trong nhà, sân vườn hoặc có thể ăn trái.</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Cà chua giúp ngăn ngừa ung thư&nbsp;<br />\r\n- Cà chua điều hòa huyết&nbsp;<br />\r\n- Cà chua cải thiện sức khỏe da.&nbsp;<br />\r\n- Giảm Cholesterol và tăng cường sức khỏe tim mạch.&nbsp;<br />\r\n- &nbsp;Hỗ trợ giảm cân.&nbsp;<br />\r\n- Cà chua cải thiện thị lực.&nbsp;<br />\r\n- Cà chua tăng cường sức khỏe não bộ</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Thu hoạch 55 - 60 ngày.<br />\r\n- Hướng dẫn trồng chậu: xem trong bao bì &nbsp;&nbsp;</p>\r\n\r\n<p>******************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '19000', '', 'en', 178),
(179, 'Phân Bón Lá Đầu Trâu Đa Năng 17-12-17+Te Cao Cấp 1Kg', '<p>- Khối lượng: 1kg<br />\r\n- Kích thước: dài x rộng x cao: 19x4x26cm</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Cung cấp đầy đủ dinh dưỡng thiết yếu cho cây cảnh và hoa giai đoạn cây con, sau khi cắt cành, trước trổ hoa.&nbsp;<br />\r\n- Kích ra rễ mạnh, đâm chồi, ra lá nhanh, cây phát triển xanh tốt.<br />\r\n- Thúc đẩy phân hóa mầm hoa mạnh, ra hoa nhiều.<br />\r\n- Phục hồi nhanh sau khi cắt tỉa, đốn cành.<br />\r\n- Tăng sức chống chịu khi thời tiết không thuận lợi.<br />\r\n- Sử dụng bón cho tất cả các loại cây trồng như rau màu, hoa &amp; cây kiểng, phong lan, cây ăn trái,...</p>\r\n\r\n<p><strong>THÀNH PHẦN CHÍNH:</strong><br />\r\n- Nts 17 %; P2O5hh 12 %; K2Ohh 7 %</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Hoa ngắn ngày: bón 20 – 30 gam/1 m2, định kỳ 20 - 25 ngày/lần.&nbsp;<br />\r\n- Hoa dài ngày: bón 30 – 40 gam/ 1 m2, định kỳ 30 – 40 ngày/lần.&nbsp;<br />\r\n- Cây cảnh, bonsai: bón 20 – 30 gam/chậu, định kỳ 30 ngày/lần.<br />\r\n- Cỏ sân vườn (cỏ nhung), cây trồng khác: bón 1 – 1,5 kg/100 m2/lần, thời kỳ cây con, tạo cành lá và trước ra hoa.&nbsp;</p>\r\n\r\n<p>***********************************************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '68000', '', 'en', 179),
(180, 'Phân Bón Đầu Trâu Đa Năng 20-20-15 1Kg', '<p>- Khối lượng: 1kg<br />\r\n- Kích thước: dài x rộng x cao: 19x4x26cm</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Cung cấp đầy đủ dinh dưỡng thiết yếu cho rau màu, hoa và cây cảnh giai đoạn cây con, sau khi cắt cành, trước trổ hoa và sau thu hoạch.&nbsp;<br />\r\n- Kích thích ra rễ mạnh, đâm chồi, ra lá nhanh, cây phát triển xanh tốt.&nbsp;<br />\r\n- Thúc đẩy phân hóa mầm hoa mạnh, ra hoa nhiều, tập trung, tăng tỷ lệ đậu trái.&nbsp;<br />\r\n- Phục hồi nhanh sau khi hoa và cây cảnh cắt tỉa, đốn cành.&nbsp;<br />\r\n- Tăng sức chống chịu của cây trồng khi thời tiết không thuận lợi.&nbsp;<br />\r\n- Tăng năng suất cây trồng.</p>\r\n\r\n<p><strong>THÀNH PHẦN CHÍNH:</strong><br />\r\n- Nts 20 %, P2O5hh 20 %, K2Ohh 15 %, + TE (MgO, Cu, Zn): 300 ppm</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\nHiệu quả cao cho cây con, thúc ra hoa, nuôi trái non.&nbsp;<br />\r\n- Rau màu: Bón 1- 1.5 kg/100 m2/lần, định kỳ 15 – 20 ngày/lần.&nbsp;<br />\r\n- Hoa: Bón 20 – 30 gram/chậu (chứa khoảng 0.02 – 0.03 m3)/lần, nếu trồng ngoài đất, bón 150 – 200 gram/10 m2/lần, định kỳ 20 – 25 ngày/lần.&nbsp;<br />\r\n- Cây cảnh, bonsai: Bón 20 – 30 gram/chậu/lần, định kỳ 1 tháng/lần.&nbsp;<br />\r\n- Cây trồng khác: Bón 1 – 1.5 kg/100 m2/lần, ở thời kỳ cây con, trước ra hoa và nuôi trái.&nbsp;<br />\r\nLượng phân bón tăng hay giảm tùy theo thể tích đất trong chậu, phân được lấp đất và tưới nước ngay sau khi bón phân.&nbsp;<br />\r\n- Chỉ sử dụng cho cây trồng.&nbsp;<br />\r\n- Bảo quản nơi khô, thoáng mát, đóng kín miệng bao sau khi sử dụng.&nbsp;<br />\r\n- Để xa tầm tay trẻ em.&nbsp;<br />\r\n- Trang bị bảo hộ lao động khi sử dụng.</p>\r\n\r\n<p>*********************************************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '68000', '', 'en', 180),
(181, 'Phân Bón Dưỡng Hoa Chuyên Hoa KiểNg (Phân ĐầU Trâu 901) 100G', '<p>- Khối lượng: 100g<br />\r\n- Kích thước: dài x rộng x cao:5x5x11cm</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Phun khi hoa đã ra nụ đến khi hoa nở<br />\r\n- Phát hoa lớn, cánh hoa dày, màu sắc đẹp, hương thơm tự nhiên.<br />\r\n- Hoa lâu tàn, đậu trái nhiều, dưỡng trái tốt với các loại cây có trái.<br />\r\n- Tăng sức chống chịu của cây trồng khi thời tiết không thuận lợi.</p>\r\n\r\n<p><strong>THÀNH PHẦN CHÍNH:</strong><br />\r\n- N: 15 %, P2O5: 20 %, K2O: 25 %, CaO: 0.05 %, MgO: 0.05 %, TE (B, Cu, Fe, Mn, Zn): 2200 ppm, NAA: 200 ppm, GA3: 100 ppm.</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n-- Lan đã ra nụ: Pha 2-3 gr/1 lít nước, phun định kỳ 5-7 ngày/lần.<br />\r\n- Hoa ngắn ngày: Pha 1-2 gr/1 lít nước, phun định kỳ 7-10 ngày/lần khi đã có nụ.<br />\r\n- Hoa dài ngày: Pha 2-4 gr/1 lít nước, phun định kỳ 7-10 ngày/lần khi đã có nụ.<br />\r\n- Cây kiểng, bonsai: Pha 1-2 gr/1 lít nước, phun định kỳ 7-10 ngày/lần.<br />\r\n- Cây cảnh có trái: Pha 2-3 gr/1 lít nước, phun trước và sau khi đậu trái, nuôi trái, định kỳ 10-15 ngày/lần.<br />\r\n- Rau trong bồn khay: Pha 1-2 gr/1 lít nước, phun 5-7 ngày/lần.<br />\r\n- Chỉ sử dụng cho cây trồng, bảo quản nơi khô, thoáng mát.<br />\r\n- Để xa tầm tay trẻ em.<br />\r\n- Nên phun vào sáng sớm hoặc chiều mát, tránh phun khi trời nắng gắt và gió to.<br />\r\n- Có thể pha chung với thuốc trừ sâu bệnh.</p>\r\n\r\n<p>********************************************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '34000', '', 'en', 181),
(182, 'Hạt Giống Bí Ăn Ngọn 20G', '<p>- Khối lượng: Gói 20g<br />\r\n- Kích thước: dài x rộng: 19x13cm</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:</strong><br />\r\n- Giống sinh trưởng và phát triển rất mạnh, trồng được quanh năm.<br />\r\n- Siêu ngọn (đọt), thân ngọn mập, màu xanh mướt đẹp, ăn ngọt ngon.</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Giàu chất xơ, chất chống oxi hóa và vitamin, có tính thanh nhiệt, nhuận tràng nhờ chất xơ kích thích nhu động ruột, hạn chế táo bón. Vì thế, nó tạo cảm giác no nhanh và hạn chế khả năng nạp năng lượng.<br />\r\n- Người bị tiểu dắt, bị sỏi đường tiết niệu ở mức nhẹ, ăn ngọn bí đỏ có thể giúp giảm triệu chứng đau, lợi tiểu và loại bỏ sỏi thông qua bài tiết tự nhiên.<br />\r\n- Trị long đờm: những chiếc lông tơ nhỏ li ti trên ngọn bí có tác dụng làm thanh phổi hiệu quả, hỗ trợ điều trị bệnh ho có đờm. Ngọn bí đỏ cắt lúc đang tươi nguyên, ngâm rửa sạch sẽ và sử dụng dài kỳ cho người bị bệnh ho liên tục.<br />\r\n- Khi bị bỏng, có thể xay nước ngọn bí thành sinh tố rồi bôi lên vùng bị bỏng nhiều lần vết bỏng nhanh “nguội”, đỡ rát, và nhanh khô miệng.</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Thời gian bắt đầu thu hoạch: 40-45 ngày sau gieo, thu hoạch kéo dài bằng cách cắt ngọn (đọt ) và bón phân hợp lý.<br />\r\n- Hướng dẫn trồng chậu: xem trong bao bì &nbsp;&nbsp;</p>\r\n\r\n<p>*************************************************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '14500', '', 'en', 182),
(183, 'Xơ Dừa Trồng Lan +  Cây Kiểng Hapi Green 200G', '<p>- Khối lượng: 200g<br />\r\n- Kích thước: dài x rộng x cao: 30x20x7cm</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Xơ dừa là một trong những giá thể được sử dụng phổ biến để trồng cây phong lan vì nó vừa&nbsp;<br />\r\ngiữ được độ ẩm cao, đồng thời cũng cung cấp dưỡng chất cho cây.<br />\r\n- Xơ dừa miếng thoáng khí, giữ ẩm tốt, kích thích bộ rễ cây phát triển mạnh.<br />\r\n- Sản phẩm đã qua xử lý không còn mầm bệnh giúp cây khỏe và phát triển tốt.<br />\r\n***************************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '24000', '', 'en', 183),
(184, 'Hạt Giống Đậu Bắp Đỏ Tím 5G', '<p>- Khối lượng: Gói 5g<br />\r\n- Kích thước: dài x rộng: 19x13cm</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:</strong><br />\r\n- Trồng quanh năm, trái dài 18 - 20cm, đường kính 14 - 16cm, màu tím đỏ<br />\r\n- Ăn ngon ngọt, ít xơ, trọng lượng: 18 - 22g một trái</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Ngăn ngừa bệnh thiếu máu, chữa ho và viêm họng, hỗ trợ trị bệnh tiểu đường, cải thiện sinh lý phái mạnh.&nbsp;<br />\r\n- Giảm mức cholesterol, hỗ trợ cho hệ tiêu hóa, cải thiện hệ miễn dịch, giúp làm đẹp làn da.</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Khoảng cách trồng: hàng cách hàng 100cm, cây cách cây: 50 - 60cm.&nbsp;<br />\r\n- Mật độ trồng/1000m2: 250 - 300g.&nbsp;<br />\r\n- Thu hoạch: 40 - 45 ngày sau gieo<br />\r\n***********************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '21000', '', 'en', 184),
(185, 'Hạt Giống Hoa Hướng Dương Xù 1G', '<p>- Khối lượng: Gói 1g<br />\r\n- Kích thước: dài x rộng: 19x13cm</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:</strong><br />\r\n- Chủng loại hướng dương kép xù, thích hợp trồng chậu, trồng thảm trang trí. Cây cao 80 cm, hoa kép, màu vàng, có phân nhánh&nbsp;</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Hạ huyết áp và giảm đau.<br />\r\n- Rễ và lõi thân tiêu viêm, lợi tiểu, chống ho và giảm đau.&nbsp;<br />\r\n- Lá tiêu viêm, giảm đau, trị sốt rét. &nbsp;&nbsp; &nbsp;<br />\r\n- Hạt trị lỵ, bổ cho dịch thể, xúc tiến bệnh sởi chóng phát ban.</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Hạt nảy mầm sau 5-7 ngày, thời gian ra hoa: 65-75 ngày<br />\r\n- Hướng dẫn trồng chậu: xem trong bao bì &nbsp;&nbsp;</p>\r\n\r\n<p>******************************************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '20800', '', 'en', 185),
(186, 'Dung Dịch Thủy Canh Rau Ăn Quả Hydro Umat F (Bộ 2 Chai)', '<p><strong>Thủy Canh Rau Ăn Lá Hydro Umat V (Bộ 2 Chai)</strong><br />\r\n- Dung tích: 1 bộ gồm 2 chai mỗi chai có dung tích 0,5 Lít. Pha được 200 lít dung dịch thủy canh<br />\r\n- Kích thước: dài x rộng x cao: 9x6x12cm<br />\r\n<strong>Thủy Canh Rau Ăn Quả Hydro Umat F (Bộ 2 Chai)</strong><br />\r\n- Dung tích: 1 bộ gồm 2 chai mỗi chai có dung tích 0,5 Lít. Pha được 200 lít dung dịch thủy canh<br />\r\n- Kích thước: dài x rộng x cao: 9x6x12cm<br />\r\n<strong>Thủy Canh Cây Cảnh Hydro Umat L (Gồm 1 chai)</strong><br />\r\n- Dung tích: 100ml pha được 20 lít dung dịch thủy canh<br />\r\n- Kích thước: dài x rộng x cao: 5x5x10cm</p>\r\n\r\n<p><strong>Thủy Canh Rau Ăn Lá Hydro Umat V (Bộ 2 Chai)</strong><br />\r\n- Dung dịch được kết hợp từ 13 nguyên tố đa lượng, vi lượng, cung cấp dưỡng chất để cây phát triển xanh tốt, tăng trưởng nhanh trong môi trường nước.<br />\r\n- Thúc đẩy cây trồng sinh trưởng mạnh mẽ hơn, giúp rễ cây hấp thụ nhanh các chất dinh dưỡng, lá cây luôn xanh tốt,…<br />\r\n<strong>Thủy Canh Rau Ăn Quả Hydro Umat F (Bộ 2 Chai)</strong><br />\r\n- Cung cấp đầy đủ cho cây trồng các dưỡng chất thiết yếu, đồng thời cân đối các thành phần dinh dưỡng, nguyên tố đa lượng, trung lượng cũng như vi lượng với mục đích tối ưu quá trình trao đổi chất cho các loại rau ăn quả.<br />\r\n- Loại dung dịch dinh dưỡng thủy canh này sẽ mang lại những nụ hoa lớn, quả đậu nhiều, đồng thời tăng cường lượng đường giúp quả có vị thơm ngọt hơn.<br />\r\n<strong>Thủy Canh Cây Cảnh Hydro Umat L (Gồm 1 Chai)</strong><br />\r\n- Duy trì sự sinh trưởng, tăng cường khả năng chống chịu, kích thích phát triển bộ rễ, hình thành lá và hoa màu sắc đẹp, duy trì độ bền cao.<br />\r\n&nbsp;</p>\r\n\r\n<p><strong>LƯU Ý</strong><br />\r\n- Dung dịch Thủy canh cũng có thể dùng để phun bón lá, tưới gốc, tưới nhỏ giọt,… công năng sử dụng cao, cung cấp đầy đủ dưỡng chất cho các loại cây trồng, nhất là cây trong giai đoạn tăng trưởng<br />\r\n- Trong nắp đậy có vạch chia thể tích, rất tiện dụng khi đong đo lượng dung dịch. Nên lắc đều bình dung dịch trước khi sử dụng<br />\r\n- Để dung dịch tại nơi khô thoáng, tránh ánh nắng trực tiếp từ mặt trời, Che chắn, tránh nước mưa làm loãng sản phẩm, ảnh hưởng đến chất lượng. Đậy kín nắp sản phẩm nếu chưa sử dụng hết để đảm bảo an toàn</p>\r\n\r\n<p>***********************************************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎Zalo: 0966440990</p>\r\n', '', '98500', '', 'en', 186),
(187, 'Bộ 3 Phân Bón Lá Đầu Trâu 501 + 701 + 901 (Nảy Chồi + Ra Lá + Kích Hoa + Nhiều Hoa + Đậu Trái)', '<p>- Khối lượng: 100g (một hũ), 300g (3 hũ)<br />\r\n- Kích thước: dài x rộng x cao: 5x5x11cm (một hũ)</p>\r\n\r\n<p><strong>Đầu Trâu 501</strong><br />\r\n- Tăng khả năng nảy chồi, ra lá các cây hoa, bonsai, cây kiểng, cỏ trồng và các cây&nbsp;<br />\r\ntrồng khác.<br />\r\n- Đặc biệt thích hợp cho giai đoạn cây con đang tăng trưởng mạnh và sau khi cắt tỉa tạo hình.<br />\r\n<strong>Đầu Trâu 701</strong><br />\r\n- Sử dụng cho giai đoạn chuẩn bị bước sang giai đoạn chuẩn bị ra hoa, kích thích hoa trổ đều và đồng loạt, tránh hiện tượng rụng hoa.<br />\r\n- &nbsp;Kích thích phân hóa mầm hoa, giúp hoa ra sớm, nhiều hoa, hoa đẹp và lâu tàn, hương thơm tự nhiên.<br />\r\n<strong>Đầu Trâu 901</strong><br />\r\n- Phun khi cây đã ra nụ đến khi hoa nở.<br />\r\n- Phát hoa lớn, cánh hoa dày, màu sắc đẹp, hương thơm tự nhiên.<br />\r\n- Hoa lâu tàn, đậu trái nhiều, dưỡng trái tốt với các loại cây cảnh có trái.<br />\r\n********************************************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎Zalo: 0966440990</p>\r\n', '', '99000', '', 'en', 187),
(188, 'Hạt Giống Hoa Thược Dược Mix Gói 10 Hạt', '<p>- Khối lượng: Gói 10 Hạt<br />\r\n- Kích thước: dài x rộng: 16x11cm</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:</strong><br />\r\n- Cây thân thảo, cao 50 - 60cm, giống hoa kép đẹp, nhiều màu sắc, cây ưa ấm và hơi khô, dễ trồng trên đất cát, tơi xốp thoát nước, đất trung tính hoặc hơi kiềm.<br />\r\n- Thược dược ưa sáng tránh nắng, mùa hè ưa mát mẻ, thích mọc nơi nửa bóng nửa sáng, có khả năng chịu rét, chịu hạn.&nbsp;</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Một lọ hoa thược dược sẽ giúp không gian trong gia đình bạn trở nên đầm ấm vui vẻ hơn.&nbsp;<br />\r\n- Nếu thực sự yêu thích vẻ đẹp của loại hoa này, bạn có thể trồng những chậu cây thược dược để bày trên ban công, trong vườn hoặc đặt trước cửa nhà để hút vận may.</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Hạt nảy mầm sau 3 - 5 ngày.&nbsp;<br />\r\n- Thời gian ra hoa: 70 - 80 ngày<br />\r\nKỹ thuật trồng chậu: Xem trong bao bì</p>\r\n\r\n<p>**************************************************************************************************</p>\r\n\r\n<p>Cửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '20800', '', 'en', 188),
(189, 'Hạt Giống Xà Lách Xoăn Cao Sản', '<p>- Khối lượng: Gói 5g, Gói 50g<br />\r\n- Kích thước: dài x rộng: 19x13cm</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:</strong><br />\r\n- Lá màu xanh sáng, có viền gợn sóng, độ đồng đều cao, chịu nhiệt tốt, lá khỏe, không bị rách khi gặp mưa, thích hợp điều kiện khí hậu nhiệt đới.</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Bổ sung chất xơ, hỗ trợ giảm cân, tốt cho tim mạch, tiểu đường, giảm cholesterol, chống oxy hóa.<br />\r\n- Giải độc bàng quang, giảm hen xuyễn, bổ sung vitamin nhóm B.<br />\r\n- Uống nước ép rau xà lách xoăn kết hợp với nước ép cà rốt, cần tây sẽ làm dịu cổ họng.<br />\r\n- Chứa kali là một chất điện phân trong tế bào quan trọng giúp chống lại sự tăng huyết áp do natri.</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Cây cao 28-35 cm, thu hoạch 28-35 ngày sau khi gieo.<br />\r\n- Khoảng cách trồng: 20-22cm.&nbsp;<br />\r\n- Mật độ trồng/1000m2: 40-50g<br />\r\n- Kỹ thuật trồng chậu xem trong bao bì<br />\r\n***********************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '13000', '', 'en', 189),
(190, 'Hạt Giống Dưa Hấu F1 1G', '<p>- Khối lượng: Gói 1g<br />\r\n- Kích thước: dài x rộng: 19x13cm</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:</strong><br />\r\n- Rễ cái dưa hấu là một trục chung quanh, và có những rễ phụ mọc ngang.&nbsp;<br />\r\n- Lá cây dưa hấu có lông ở gân mặt dưới, mang bởi 1 cuống dài 5 đến 15cm được bao phủ bởi lông tơ nhất là những lá non.&nbsp;<br />\r\n- Phiến lá dưa hấu xanh tươi, có dạng hình bầu dục, đơn và mọc cách, dài khoảng 10-15cm, rộng 7-12cm.<br />\r\n- Sinh trường mạnh, kháng bệnh tốt, trong quanh năm (miền Nam).<br />\r\n- Trái dài, mập, nặng 4-6kg, màu xanh đen, sọc mờ, vỏ dày trung bình.&nbsp;<br />\r\n- Ruột đỏ đậm, ăn ngon, độ đường cao, khả năng vận chuyển xa tốt.&nbsp;</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Tác dụng của dưa hấu tới tim mạch và xương cốt.&nbsp;<br />\r\n- Tiêu giảm mỡ trong cơ thể.<br />\r\n- Chống viêm nhiễm và chống ôxy hóa.<br />\r\n- Lợi tiểu, bổ thận.&nbsp;<br />\r\n- Bổ trợ cơ bắp và hệ thần kinh.&nbsp;<br />\r\n- Tăng cường sự hình thành kiềm.&nbsp;<br />\r\n- Tăng cường thị lực.&nbsp;<br />\r\n- Miễn dịch, hồi phục vết thương và bảo vệ tế bào.<br />\r\n- Hướng dẫn trồng chậu: xem trong bao bì &nbsp;&nbsp;</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Thời gian thu hoạch 55-60 ngày giau seo, năng suất 30-40 tấn/ha.<br />\r\n- Hướng dẫn trồng chậu: xem trong bao bì &nbsp;&nbsp;</p>\r\n\r\n<p>***********************************************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '23000', '', 'en', 190),
(191, 'Phân Hữu Cơ Tan Chậm 15 Túi Bounce Back (Phân Bón Chuyên Phong Lan) 90G', '<p>- Khối lượng: 90g gốm 15 túi lọc (6g/túi lọc)<br />\r\n- Kích thước: dài x rộng x cao: &nbsp;15x8x4cm<br />\r\n- Phân túi lọc cao cấp Bounce Back Neutrog là loại phân bón hữu cơ chuyên dùng cho phong lan, cây kiểng, bonsai từ nhỏ tới trưởng thành.</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n-Sản phẩm được đóng gói hợp vệ sinh, gồm 15 túi lọc, mỗi túi lọc 6g với cách sử dụng đơn giản cho hiệu quả lâu dài.<br />\r\n- Sản phẩm 100% thiên nhiên, tan chậm trong đất và thân thiện với môi trường. Phân bón cung cấp đầy đủ chất dinh dưỡng, đa - trung - vi lượng, giúp cây trồng phát triển mạnh, phòng chống các loại sâu bệnh.&nbsp;<br />\r\n- Không mang mầm bệnh và không gây cháy lá.<br />\r\n- Làm cho đất thông thoáng, kích thích hệ vi sinh vật, trùn đất.&nbsp;<br />\r\n- Nên bón và lấp đất để tăng hiệu quả tối ưu của phân Bounce Back.</p>\r\n\r\n<p>*******************************************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '33500', '', 'en', 191),
(192, 'Phân Bón Nảy Chồi Ra Lá Chuyên Hoa Kiểng (Phân ĐầU Trâu 501) 100G', '<p>- Khối lượng: 100g<br />\r\n- Kích thước: dài x rộng x cao: 5x5x11cm</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Giúp cây phát triển thân cành lá<br />\r\n- Phun khi cây còn nhỏ, sau cắt hoa, chuyển chậu<br />\r\n- Giúp cây con ra nhiều chồi mới, thân lá phát triển nhanh.<br />\r\n- Đặc biệt thích hợp cho giai đoạn cây con đang tăng trưởng mạnh và sau khi cắt tỉa tạo hình.<br />\r\n- Tăng sức chống chịu của cây trồng khi thời tiết không thuận lợi.<br />\r\n- Bón cho tất cả các loại cây trồng như rau màu, phong lan, hoa và cây kiểng, cây ăn trái,....</p>\r\n\r\n<p><strong>THÀNH PHẦN CHÍNH:</strong><br />\r\n- N: 30 %, P2O5: 15 %, K2O: 10 %, CaO: 0.05 %, MgO: 0.05 %, TE (B, Cu, Fe, Mn, Zn): 1850 ppm, NAA: 200 ppm, GA3: 100 ppm.</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Lan còn nhỏ, chưa ra hoa: Pha 1 gr/1 lít nước, phun định kỳ 5-7 ngày/lần.<br />\r\n- Lan sau khi cắt hoa, chuyển chậu: Pha 2-3gr/1 lít nước, phun định kỳ 7-10 ngày/lần.<br />\r\n- Hoa ngắn ngày: Pha 1-2gr/1 lít nước, phun định kỳ 7-10 ngày/lần trong thời kỳ cây tăng trưởng và sau cắt hoa.<br />\r\n- Hoa dài ngày: Pha 2-4gr/1 lít nước, phun định kỳ 7-10 ngày/lần.<br />\r\n- Cây kiểng, bonsai: Pha 2-3 gr/1 lít nước, phun định kỳ 7-10 ngày/lần khi cây đang lớn hoặc sau cắt tỉa cành.<br />\r\n- Rau trong bồn khay: Pha 1-2gr/1 lít nước, phun &nbsp;3-5 ngày/lần.<br />\r\n- Chỉ sử dụng cho cây trồng, bảo quản nơi khô, thoáng mát.<br />\r\n- Để xa tầm tay trẻ em.<br />\r\n- Nên phun vào sáng sớm hoặc chiều mát, tránh phun khi trời nắng gắt và gió to.<br />\r\n- Có thể pha chung với thuốc trừ sâu bệnh.</p>\r\n\r\n<p>********************************************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '34000', '', 'en', 192),
(193, 'Hạt Giống Hoa Sao Nhái Kép Mix 20H', '<p>- Khối lượng: Gói 20 hạt<br />\r\n- Kích thước: dài x rộng: 16x11cm</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:</strong><br />\r\n- Là dòng hoa dạng lùn thích hợp cho trồng chậu, trồng thảm, cây có khả năng chịu nóng và phân nhánh tốt<br />\r\n- Là loại hoa dễ trồng, dễ chăm sóc, sinh trưởng nhanh<br />\r\n- Hoa kép nhiều màu, cây cao 25-30cm, đường kính hoa khoảng 3-4cm, màu hoa: cam và vàng</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Thời gian sang chậu ( kể từ ngày gieo ): 10-15 ngày.<br />\r\n- Thời gian ra hoa ( kể từ ngày sang chậu ): 35-45 ngày.</p>\r\n\r\n<p>**********************************************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '19000', '', 'en', 193),
(194, 'Hạt Giống Hoa Cúc Lá Nhám Mix 1G', '<p>- Khối lượng: Gói 1g&nbsp;&nbsp; &nbsp;<br />\r\n- Kích thước: dài x rộng: 19x13cm</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:</strong><br />\r\n- Cây cao 50-60 cm, hoa nhỏ, gọn, có màu tươi sáng phối trộn đa dạng, thân cây cứng lâu tàn rất thích hợp cho cắt cành, cắm bình.&nbsp;<br />\r\n- Cây dễ trồng, ưa nắng, chịu hạn tốt, rễ phát triển mạnh ít bị ngã.</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Cúc lá nhám trồng để trang trí, để xung quanh nhà, hay góc sân vườn.<br />\r\n- Ngoài ra những hội triển lãm hoa xuân cũng thường sử dụng loại cúc này để trang trí phối kết.</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Hạt nẩy mầm sau 3-5 ngày<br />\r\n- Thời gian ra hoa: 60-70 ngày<br />\r\n- Hướng dẫn trồng chậu: xem trong bao bì &nbsp;&nbsp;</p>\r\n\r\n<p>*************************************************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '20800', '', 'en', 194),
(195, 'Hạt Giống Rau Dền Tiều', '<p>- Khối lượng: Gói 20g, Gói 50g<br />\r\n- Kích thước: dài x rộng: 19x13cm</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:</strong><br />\r\n- Trồng quanh năm. Cây sinh trưởng mạnh, kháng bệnh tốt. Cây cao 25-35cm, lá lớn, mềm, không xơ</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Tốt cho xương khớp.&nbsp;<br />\r\n- Giảm viêm.&nbsp;<br />\r\n- Tốt cho bệnh tiểu đường.&nbsp;<br />\r\n- Ngăn ngừa các vấn đề răng miệng.&nbsp;<br />\r\n- Ngừa bệnh tim mạch.&nbsp;<br />\r\n- Cải thiện chứng thiếu máu.&nbsp;<br />\r\n- Cải thiện hệ tiêu hóa.&nbsp;<br />\r\n&nbsp;&nbsp; &nbsp;<br />\r\n<strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Thu hoạch: 25-30 ngày sau gieo<br />\r\n- Khoảng cách trồng: Hàng cách hàng: 10-15cm, cây cách cây: 10-15cm.&nbsp;<br />\r\n- Mật độ trồng/1000m2: Gieo sạ: 200-300g, gieo cấy: 70-100g<br />\r\n<strong>Kỹ thuật trồng chậu</strong>: Xem trong bao bì<br />\r\n**********************************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '12000', '', 'en', 195),
(196, 'Hạt Giống Rau Sam 2G', '<p>- Khối lượng: Gói 2g<br />\r\n- Kích thước: dài x rộng: 19x13cm</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:</strong><br />\r\n- Rau sam ưa ẩm, dễ trồng, sinh trưởng rất khỏe, vừa làm rau ăn vừa làm vị thuốc quý.<br />\r\n- Thân nhiều cành mẩm nhẵn màu đỏ nhạt, mọc bò lan mặt đất.<br />\r\n- Lá hình răng ngựa không cuống, phiến lá dày, mặt láng</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Chứa nhiều vitamin- khoáng chất (A, B1, B2, C, PP..) và acid béo omega - 3&nbsp;<br />\r\n- Rất tốt cho sức khỏe, tác dụng &nbsp;giúp vết thương mau lành hạ hỏa chống lão hóa.<br />\r\n- Hỗ trợ tốt trong điều trị bệnh Gút, phòng ngừa tim mạch.</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Kỹ thuật trồng chậu: xem trong bao bì</p>\r\n\r\n<p>******************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '21000', '', 'en', 196),
(197, 'Hạt Giống Rau Kinh Giới 2G', '<p>- Khối lượng: Gói 2g<br />\r\n- Kích thước: dài x rộng: 19x13cm</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:</strong><br />\r\n- Dạng cây thân bụi, lá màu xanh rìa răng cưa, vị the mát, mùi thơm hấp dẫn.</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Kinh giới thúc đẩy tuyến mồ hôi phân tiết giải co cứng, đẩy mạnh tuần hoàn máu, ngoài da, tiêu viêm, an thần, hạ sốt, giãn phế quản, chống dị ứng.&nbsp;<br />\r\n- Lá kinh giới có mùi thơm dễ chịu, vị cay, tính ấm, có chứa 1% tinh dầu.&nbsp;<br />\r\n- Kinh giới được dùng làm thuốc trị các bệnh: ngoại cảm phong tà, phát sốt, nhức đầu, tắc mũi, ho, mẩn ngứa; sởi mới phát, mụn nhọt, đau họng, thũng độc; chảy máu cam, ho, nôn ra máu, đại tiểu tiện ra máu, rong kinh, băng huyết; sản hậu, cấm khẩu, tứ chi co quắp.</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n-Thu hoạch 50-55 ngày sau khi gieo, cắt cây hoặc ngắt đọt.<br />\r\n- Khoảng cách trồng: 20x20cm. Mật độ trồng/1000m2: 60-70g&nbsp;<br />\r\n- Kỹ thuật trồng chậu xem trong bao bì<br />\r\n***********************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '14500', '', 'en', 197),
(198, 'Hạt Giống Rau Đay Trắng 20G', '<p>- Khối lượng: Gói 20g<br />\r\n- Kích thước: dài x rộng: 19x13cm</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:</strong><br />\r\n- Kháng bệnh tốt, lá to, màu xanh non, ngọt thơm, không có mùi hăng nồng, thân mềm, cây cao 25 - 30cm.&nbsp;</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Bổ sung sắt, ngăn ngừa thiếu máu.&nbsp;<br />\r\n- Ăn rau đay nhuận tràng, chống táo bón.&nbsp;<br />\r\n- Lợi sữa.&nbsp;<br />\r\n- Thông tiểu, ngăn ngừa viêm nhiễm đường tiết niệu.&nbsp;<br />\r\n- Giải nhiệt, tiêu độc.&nbsp;<br />\r\n- Nâng cao sức khỏe tim mạch.&nbsp;<br />\r\n- Chống còi xương.&nbsp;<br />\r\n- Rau đay chữa rắn cắn.</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Khoảng cách trồng: Hàng x hàng 20cm, Cây x cây 20cm.<br />\r\nThu hoạch: 30 - 35 ngày sau gieo .<br />\r\n<strong>Kỹ thuật trồng chậu</strong>: Xem trong bao bì</p>\r\n\r\n<p>**************************************************************************************************</p>\r\n\r\n<p>Cửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '13000', '', 'en', 198),
(199, 'Hạt Giống Hoa Cẩm Chướng Đơn Telstar Mix 10H', '<p><strong>MÔ TẢ:</strong><br />\r\n- Khối lượng: Gói 10 hạt<br />\r\n- Kích thước: dài x rộng: 16x11cm</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:</strong><br />\r\n- Là dòng hoa cẩm chướng đơn, phân nhanh tốt và cho những bông hoa rất đẹp.<br />\r\n- Cây cao 25-30cm, đường kinh hoa 3-3.5 cm, màu sắc: nhiều màu</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Cẩm chướng đơn có nhiều màu sắc rực rỡ thích hợp trang trí nhà cửa giúp thư giãn tinh thần.<br />\r\n- Bên cạnh đó cẩm chướng có vị đắng, tính hàn, tác dụng lợi tiểu, thông lâm, hoạt huyết, thông kinh, chữa đái buốt, đái dắt, đái ra máu, đái ra sỏi, tiểu tiện không thông, bế kinh, phù thũng, trừ giun, lá dùng chữa tắc ruột.&nbsp;</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Thời gian sang chậu ( kể từ ngày gieo ) 25-30 ngày<br />\r\n- Thời gian ra hoa ( kể từ ngày sang chậu ) 65-70 ngày<br />\r\nKỹ thuật trồng chậu: Xem trong bao bì<br />\r\n****************************************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '25000', '', 'en', 199),
(200, 'Hạt Giống Ớt Xiêm Xanh 5gr + gói lớn', '<p>- Khối lượng: Gói lớn 5gr<br />\r\n- Kích thước: dài x rộng: 16x11cm</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:</strong><br />\r\n- Là loại ớt cay, dễ trồng, thích nghi với nhiều loại đất<br />\r\n- Ớt trái nhỏ, chiều dài 1.5cm-3cm, có vị cay nồng, có mùi thơm hấp dẫn</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Thu hoạch 75-80 ngày sau khi gieo hạt. Có thể ăn trái khi ớt còn xanh, hái liên tục kéo dài.<br />\r\nKỹ thuật trồng chậu: Xem trong bao bì</p>\r\n\r\n<p>**************************************************************************************************</p>\r\n\r\n<p>Cửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh</p>\r\n\r\n<p>☎ 0966440990</p>\r\n', '', '215000', '', 'en', 200),
(201, '[Túi Lớn 1Kg] Hạt Giống Mầm Rau Muống Dễ Trồng + Rau Sạch Trồng Ban Công', '<p>- Khối lượng: Gói 1 kg<br />\r\n- Kích thước: dài x rộng: 28x20cm<br />\r\n- Hiện shop có bán hàng gói nhỏ 50g (16x11cm), 100g (19x13cm)&nbsp;<br />\r\nQuý khách có thể tìm sản phẩm với tên \"Hạt Giống Rau Muống Cao Sản\" hoặc link<br />\r\nhttps://shopee.vn/Hạt-Giống-Rau-Muống-Cao-Sản-i.237010465.7826059508</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:</strong><br />\r\n- Rau mầm rau muống là mầm của cây rau muống thân mập mướt, có vị ngọt mát, có tính thanh nhiệt giải độc rất tốt cho cơ thể.&nbsp;<br />\r\n- Rau mầm rau muống là loại rau dễ trồng, dễ chăm sóc, an toàn và giàu dinh dưỡng, rất thích hợp trồng tại nhà cung cấp cho gia đình một món ăn vừa an toàn, vừa ngon miệng.</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Giảm say nắng hiệu quả với những người bị khó tiêu ăn rau muống mầm cực kì nhuận tràng, tiêu hóa dễ, trị táo bón.<br />\r\n- Hàm lượng chất dinh dưỡng cao của rau muống mầm còn giúp cơ thể kháng bệnh tốt, tăng khả năng đề kháng với các bệnh cảm cúm, sốt thường gặp</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Thu hoạch: 8 – 10 ngày sau gieo. Năng suất 530 – 630g rau/100g hạt&nbsp;<br />\r\nKỹ thuật trồng mầm: xem trong bao bì</p>\r\n\r\n<p>*************************************************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '99000', '', 'en', 201),
(202, 'Hạt Giống Cải Bẹ Dún', '<p>- Khối lượng: Gói 10g, Gói 50g<br />\r\n- Kích thước: dài x rộng: 19x13cm</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:</strong><br />\r\n- Cây sinh trưởng phát triển nhanh, kháng bệnh tốt, có thể trồng được quanh năm.<br />\r\n- Lá có xanh nhạt, trồng khí hậu lạnh sẽ đóng bắp.</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Chữa xuất huyết do loét dạ dày hoặc loét hành tá tràng.<br />\r\n- Chứa các chất chống oxy hóa cao giúp trẻ hóa làn da.<br />\r\n- Giúp giảm cân, ngừa giảm trí nhớ.</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Khoảng cách trồng hàng cách hàng 15 - 20cm, cây cách cây 15cm.<br />\r\n- Mật độ trồng 1000m2: 120 - 150g.<br />\r\n- Kỹ thuật trồng chậu xem trong bao bì.<br />\r\n***********************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '10900', '', 'en', 202),
(203, '[Túi Lớn 1Kg] Hạt Giống Rau Mầm Hướng Dương Dễ Trồng- Rau Sạch- Giàu Vitamin- Đẹp Da- Tốt Cho Tim Mạch', '<p>- Khối lượng: gói 1kg<br />\r\n- Kích thước: dài x rộng: 36x26cm</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:</strong><br />\r\n- Mầm hướng dương rất giàu dinh dưỡng, có vị ngon ngọt, béo và the mát, có thể ăn sống hoặc nấu chín</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Rau mầm hạt hướng dương là một loại thức ăn ngon miệng và rất bổ dưỡng, bởi hạt hướng dương có chứa đến 25% protein, rất nhiều chất kẽm và vitamin B, E, đặc biệt tốt cho phụ nữ đang mang thai bởi giúp phát triển các tế bào thần kinh cho trẻ ngay trong giai đoạn bào thai.&nbsp;<br />\r\n- Rau mầm hạt hướng dương còn giúp tăng cường khả năng hô hấp ở người lớn tuổi, giảm chứng đau thắt ngực, cao huyết áp và các bệnh về tim mạch.&nbsp;<br />\r\n- Chính công dụng tuyệt vời đó, cùng với vị ngọt, bùi rất dễ ăn của mầm cây, rau mầm hạt hướng dương là một trong những loại thực phẩm lý tưởng để chế biến nên những món salad ngon lành, bổ dưỡng cho gia đình.</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Thời gian thu hoạch: 5-7 ngày sau khi gieo.<br />\r\n- Lượng giống gieo trồng: 350-400g/m2 hoặc 25-30g/khay nhựa 20x30.<br />\r\n- Năng suất: 2,5-3kg/m2.<br />\r\n- Không nên gieo hạt quá dày, ngâm hạt trong nước ấm từ 4-6 tiếng trước khi gieo.<br />\r\nKỹ thuật trồng mầm hướng dương: xem thêm trong bao bì</p>\r\n\r\n<p>**************************************************************************************************</p>\r\n\r\n<p>Cửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '235000', '', 'en', 203),
(204, 'Hạt Giống Hoa Mào Gà Búa Lở 20H', '<p>&nbsp;- Khối lượng: Gói 20 hạt<br />\r\n- Kích thước: dài x rộng: 19x13cm</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:</strong><br />\r\n-- Cây sống dai, cao 30 - 45cm hay hơn, có thân thẳng đứng và phân nhánh.&nbsp;<br />\r\n- Lá hình bầu dục, màu xanh xám pha đỏ. &nbsp;&nbsp;<br />\r\n- Cụm hoa xòe ra ở ngọn thành hình quạt, trông giống như mào con gà trống.&nbsp;<br />\r\n- Các hoa thật tạo thành một phần hình trụ ở phía dưới các mào đó.&nbsp;</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Hoa thường được dùng đẻ làm cảnh, trang trí hành lang sân vườn, sảnh.<br />\r\n- Không chỉ có vậy chúng còn rất nhiều các tác dụng tốt cho cơ thể như đều trị cao huyết áp,&nbsp;<br />\r\nthổ huyết, giải độc rắn cắn.</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Hoa mào gà thích hợp với khí hậu ôn hòa, có thể trồng quanh năm.<br />\r\n- Tuy nhiên, vụ Đông - Xuân thường cho hoa đẹp nhất. Cây ưa nóng, không chịu rét.<br />\r\n- Mào gà là loại cây dễ trồng, muốn có hoa to, phải tỉa bớt tất cả các mầm non mọc ở nách lá và các hoa phụ.<br />\r\nKỹ thuật trồng chậu: Xem trong bao bì<br />\r\n*****************************************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '20800', '', 'en', 204),
(205, 'Hạt Giống Tỏi Tây 2G', '<p>&nbsp;- Khối lượng: Gói 2g<br />\r\n- Kích thước: dài x rộng: 19x13&nbsp;</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:</strong><br />\r\n- Tỏi tây còn gọi là hành ba rô, là loại cây thân thảo lá dẹp<br />\r\n- Cây có thân màu trắng dài khoảng 20-22cm, đường kính 2-3cm. Cây phát triển rất tốt trong điều kiện&nbsp;<br />\r\nnhiệt độ dưới 31°C.<br />\r\n<strong>CÔNG DỤNG:</strong><br />\r\n- Chống lại các gốc tự do có hại trong cơ thể.<br />\r\n- Giảm nguy cơ ung thư.<br />\r\n- Hỗ trợ sức khỏe tim mạch.<br />\r\n- Cải thiện xương.&nbsp;<br />\r\n- Giảm các bệnh mãn tính.&nbsp;<br />\r\n- Hỗ trợ tiêu hóa.&nbsp;<br />\r\n- Giảm cân.&nbsp;</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong> xem trong bao bì<br />\r\nThời gian thu hoạch ngắn: từ 100-120 ngày sau khi gieo<br />\r\n*********************************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '15000', '', 'en', 205),
(206, 'Hạt Giống Rau Mầm Giá Đậu Xanh 100G', '<p><strong>&nbsp;</strong>- Khối lượng: Gói 100g<br />\r\n- Kích thước: dài x rộng: 16x11cm<br />\r\n- Có hàng gói lớn 500g (28x20cm) với giá tiết kiệm<br />\r\nQuý khách có thể tìm sản phẩm với tên \"Hạt Giống Hạt Giống Mầm Giá Đậu Xanh 1kg\" hoặc link<br />\r\nhttps://shopee.vn/Hạt-Giống-Mầm-Giá-Đậu-Xanh-1kg-i.237010465.6240016247</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:&nbsp;</strong><br />\r\n- Hạt giống được lựa chọn kỹ không mầm bệnh.&nbsp;<br />\r\n- Cây giá lên nhanh mạnh đều.<br />\r\n- Thân trắng muốt, mềm, ăn ngon ngọt bùi.</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Giá đỗ là kho dự trữ vitamin B giúp tăng cường trao đổi chất.&nbsp;<br />\r\n- Tăng mật độ xương, ổn định cholesterol.&nbsp;<br />\r\n- Giúp tăng lưu thông khí huyết, thúc đẩy tiêu hóa.&nbsp;<br />\r\n- Giúp giảm cân, giảm căng thẳng và lo lắng.</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Thu hoạch 3 - 4 ngày sau khi ủ.<br />\r\n- Kỹ thuật trồng chậu xem trong bao bì<br />\r\n***********************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '16400', '', 'en', 206),
(207, 'Hạt Giống Hoa Mười Giờ Kép Mix 50H', '<p>&nbsp;- Khối lượng: Gói 50 hạt<br />\r\n- Kích thước: dài x rộng: 16x11cm</p>\r\n\r\n<p><strong>ĐẶC ĐIỂM:</strong><br />\r\n- Là dòng hoa thân thảo, hoa kép với nhiều màu sắc: đỏ, hồng, vàng, trắng.&nbsp;<br />\r\n- Cây cao 8 - 10cm, đường kinh hoa: 4 - 6 cm, phân nhánh tốt, hoa dễ trồng.&nbsp;</p>\r\n\r\n<p><strong>CÔNG DỤNG:</strong><br />\r\n- Chữa viêm họng: Hoa mười giờ có tác dụng chữa viêm họng rất hiệu quả. Hoa mười giờ và lá cây rẻ quạt rửa sạch, giã nhỏ. Cho nước sôi vào hoà đều rồi chắt lấy nước. Lấy nước, ngậm đều mỗi ngày 2-3 lần, dùng liên tục trong vòng 3-5 ngày sẽ thấy ngay hiệu quả tốt.<br />\r\n- Chữa bỏng nhẹ: Khi bị bỏng, việc đầu tiên bạn cần làm là ngâm ngay vết thương vào nước mát. Sau đó hái nắm cây hoa mười giờ (không kể liều lượng) đem rửa sạch, giã nhuyễn rồi đắp lên vết thương. Lưu ý vừa đắp vừa giở ra liên tục cho mát. Khi nắm lá ấm dần lên, không còn mát thì thay nắm khác, thay liên tục cho đến khi vết bỏng không còn nóng rát.</p>\r\n\r\n<p><strong>HƯỚNG DẪN SỬ DỤNG:</strong><br />\r\n- Thời gian sang chậu ( kể từ ngày gieo ): 25 - 30 ngày&nbsp;<br />\r\n- Thời gian ra hoa ( kể từ ngày sang chậu ): 35 - 45 ngày&nbsp;<br />\r\n- Hướng dẫn trồng chậu: xem trong bao bì &nbsp;&nbsp;</p>\r\n\r\n<p>*************************************************************************************************************************************<br />\r\nCửa hàng Love Green chuyên sĩ và lẻ:&nbsp;<br />\r\n✔ Hạt giống nhãn hiệu Tâm Nông<br />\r\n✔ Dụng cụ làm vườn, khay chậu<br />\r\n✔ Phân bón, đất trồng, dung dịch thủy canh<br />\r\n☎ 0966440990</p>\r\n', '', '19000', '', 'en', 207);
